import {REGIONS,PERIODS,CATEGORIES,ROLES,seedData} from './data.js';
import {sum,fillRate,averageNotice,remainingPlan,remainingTarget,compatible,potentialMatches,addMatch,completeMatch,outcomes,filterRows,balance} from './model.js';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal'), KEY='foodloop-bakery-planning-v3';
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state||state.version!==3)state=seedData();
let page=location.hash.slice(1)||'home',filters={region:'All',period:'All',category:'All'},business='All',role='All',toastTimer;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('en-AU',{maximumFractionDigits:1}),kg=n=>`${num(n)} kg`,period=id=>PERIODS.find(p=>p.id===id)?.label||id;
const button=(label,action,id='',primary=false)=>`<button ${primary?'class="primary"':''} data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const opts=(values,selected)=>values.map(v=>{let [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(label)}</option>`}).join('');
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Storage is unavailable. Changes will last for this session only.')}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function title(k,t,description,action=''){return `<section class="pageheading"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${description}</p></div>${action}</section>`}
function stat(label,value,note,tone=''){return `<article class="stat ${tone}"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`}
function filtersUI(){return `<section class="filters" aria-label="Dashboard filters"><span>View by</span><label>State / territory<select data-filter="region">${opts([['All','All Australia'],...Object.entries(REGIONS).map(([k,v])=>[k,`${v} (${k})`])],filters.region)}</select></label><label>Period<select data-filter="period">${opts([['All','All demo periods'],...PERIODS.map(p=>[p.id,p.label])],filters.period)}</select></label><label>Bakery category<select data-filter="category">${opts(['All',...CATEGORIES],filters.category)}</select></label>${button('Clear filters','clear')}</section>`}
function render(){if(!['home','business','efwa'].includes(page))page='home';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#crumb').textContent={home:'Homepage',business:'Business planning',efwa:'Demand supply chain'}[page];({home:home,business:businessPage,efwa:efwaPage})[page]()}
function home(){const b=balance(state,filters),plans=filterRows(state.plans,filters),reported=filterRows(outcomes(state),filters),edible=reported.filter(r=>r.stream==='Edible'),inedible=reported.filter(r=>r.stream==='Inedible'),people=sum(edible,'people');
app.innerHTML=title('NATIONAL BAKERY PILOT','A clearer picture. Less waste.','Connect business surplus with food demand and suitable by-product pathways.',button('+ Add business plan','plan','',true))+filtersUI()+
`<div class="stats four">${stat('Planned edible supply',kg(b.supply),'Projected surplus, not confirmed waste')}${stat('Forecast food demand',kg(b.demand),'Food use · excludes recovery capacity')}${stat('Potential food matches',kg(b.potential),'Same state, period and category','green')}${stat('Connected food volume',kg(b.reserved),'Reserved + confirmed handovers')}</div>
<div class="dashboardgrid"><section class="panel"><div class="sectionhead"><div><span class="eyebrow">SUPPLY & DEMAND</span><h2>Where can food find a home?</h2></div><span class="legend"><i class="dot supply"></i>Supply <i class="dot demand"></i>Demand</span></div><div class="regionrows">${Object.entries(REGIONS).filter(([r])=>filters.region==='All'||r===filters.region).map(([r,name])=>{const x=balance(state,{...filters,region:r}),max=Math.max(x.supply,x.demand,1);return `<button class="regionrow" data-action="region" data-id="${r}" aria-label="Filter dashboard to ${name}"><div><b>${r}</b><small>${name}</small></div><div class="barpair"><div class="supplybar" style="width:${x.supply/max*100}%"></div><div class="demandbar" style="width:${x.demand/max*100}%"></div></div><div class="regionvalues"><b>${num(x.supply)} / ${num(x.demand)} kg</b><small>${!x.supply&&!x.demand?'No plans yet':x.demand>x.supply?'Demand exceeds supply':x.supply>x.demand?'Supply exceeds demand':'Totals balanced'}</small></div></button>`}).join('')}</div><p class="footnote">Bars scale within each state. National totals alone do not establish a match.</p></section>
<section class="panel opportunities"><span class="eyebrow">PLANNING SIGNALS</span><h2>Room to connect</h2><div class="signal"><span class="signalicon green">＋</span><div><strong>${kg(b.headroom)}</strong><b>Unfilled food demand</b><p>Potential capacity for future suitable surplus. This does not prove waste has already fallen.</p></div></div><div class="signal"><span class="signalicon amber">≈</span><div><strong>${kg(b.unmatched)}</strong><b>Edible supply without a forecast match</b><p>Review orders, find other food outlets or reassess usable life. Extra supply is at risk, not automatically waste.</p></div></div><div class="signal"><span class="signalicon lavender">♧</span><div><strong>${kg(sum(plans.filter(p=>p.stream==='Inedible')))}</strong><b>Planned inedible material</b><p>Explore suitable transformation or recovery partners after material assessment.</p></div></div>${button('Explore demand planning','goto','efwa',true)}</section></div>
<section class="panel outcomes"><div class="sectionhead"><div><span class="eyebrow">REPORTED OUTCOMES</span><h2>What has actually been managed?</h2></div>${button('Export outcomes','export')}</div><p class="muted">Confirmed demo handovers only, within the selected filters. Forecasts and reserved matches are excluded.</p><div class="stats four subtle">${stat('Total managed material',kg(sum(reported)),'Edible redistribution + inedible recovery')}${stat('Edible redistributed',kg(sum(edible)),'Kept in the food supply chain')}${stat('Inedible recovered',kg(sum(inedible)),'Confirmed non-food pathways')}${stat('People served',num(people),'Reported service counts; not unique people')}</div><div class="tablewrap"><table><thead><tr><th>Category</th><th>Edible food</th><th>Inedible recovery</th><th>People served</th></tr></thead><tbody>${CATEGORIES.filter(c=>filters.category==='All'||filters.category===c).map(c=>{const rows=reported.filter(r=>r.category===c);return `<tr><td><b>${esc(c)}</b></td><td>${kg(sum(rows.filter(r=>r.stream==='Edible')))}</td><td>${kg(sum(rows.filter(r=>r.stream==='Inedible')))}</td><td>${num(sum(rows,'people'))}</td></tr>`}).join('')}</tbody></table></div><p class="footnote">People counts are reported per handover and may include repeat recipients. No kilograms-to-people conversion. ${edible.filter(r=>r.people===null).length} food handover(s) have no people count yet. Seed outcomes are in 23–29 Nov; upcoming periods start with no outcomes.</p></section>${programDetails()}`}
function programDetails(){return `<details class="programdetails"><summary>About the program · six questions answered</summary><div class="aboutgrid"><div><h3>Who’s involved?</h3><p>Farmer / supplier, manufacturer / packer and distributor. Food recipients and recovery processors provide receiving capacity.</p></div><div><h3>Who’s in charge?</h3><p>EFWA convenes a working group with each supply chain role. Partners approve operational decisions; EFWA coordinates trials and agreed measurement.</p></div><div><h3>How does it work?</h3><p>Businesses forecast material streams. EFWA maps food demand and recovery capacity. Partners reserve compatible volumes, then confirm handovers.</p></div><div><h3>How is data shared?</h3><p>Proposed model: aggregate forecasts across the network, share operational details with consent and review competition/privacy requirements before rollout. This demo has no access controls.</p></div><div><h3>Why would businesses join?</h3><p>Earlier demand visibility, potential recovered value, coordinated transport and consistent reporting. Proposed sponsor-funded collection support is subject to funding and verified participation.</p></div><div><h3>How do we know it works?</h3><p>Track confirmed weight, reported people served and business-specific waste rates and costs. Prevention needs a comparable baseline; redistribution alone does not prove prevention.</p></div></div></details>`}
function selectedPlans(){return state.plans.filter(p=>(business==='All'||p.business===business)&&(role==='All'||p.role===role))}
function businessPage(){const rows=selectedPlans();app.innerHTML=title('FOR SUPPLIERS, MANUFACTURERS & DISTRIBUTORS','Plan ahead. Find the right partner.','Record expected bakery surplus, use planning indicators and connect with suitable demand.',button('+ Create waste plan','plan','',true))+`<div class="filters"><label>Business<select id="businessfilter">${opts([['All','All demo businesses'],...new Set(state.plans.map(p=>p.business))],business)}</select></label><label>Supply chain role<select id="rolefilter">${opts([['All','All three roles'],...ROLES],role)}</select></label><span class="filterhint">Viewing demo business records · no sign-in required</span></div><div class="tip"><span>◎</span><div><b>Use indicators to start a conversation.</b> Forecast fill rate = actual volume ordered ÷ forecast volume. Average notice = total days of notice ÷ number of changes. Neither formula predicts waste automatically.</div></div><div class="sectionhead"><h2>Business waste plans <span class="count">${rows.length}</span></h2><span class="muted">Volumes are in kilograms</span></div><div class="planlist">${rows.map(planCard).join('')||'<div class="panel empty">No plans for these filters.</div>'}</div>${handovers(rows)}<section class="incentive"><div><span class="eyebrow">WHY PARTICIPATE?</span><h2>Make collaboration worth the effort.</h2><p>Recover value from suitable surplus, coordinate collections and report consistent outcomes. Proposed pilot policy: agree order-change notice periods and share cancellation costs fairly.</p></div><div><b>Collection support · proposed</b><p>Sponsor-funded support could reward verified participation and prevention. Funding, rates and eligibility are still to be agreed.</p><small>No compensation entitlement or tradable carbon credit is created.</small></div></section>`}
function planCard(p){const fr=fillRate(p.forecast,p.ordered),av=averageNotice(p.notices),remaining=remainingPlan(state,p),targets=potentialMatches(state,p);return `<article class="plan"><div class="planidentity"><div class="materialicon ${p.stream==='Edible'?'':'lavender'}">${p.category===CATEGORIES[0]?'🌾':p.stream==='Inedible'?'♧':'🍞'}</div><div><div class="badgerow">${badge(p.role)}${badge(p.stream,p.stream==='Inedible'?'purple':'green')}</div><h3>${esc(p.material)}</h3><p>${esc(p.business)} · ${p.region} · ${period(p.period)}</p><small>${esc(p.category)} · ${esc(p.reason)}</small></div></div><div class="planmetrics"><div><small>Planned volume</small><b>${kg(p.qty)}</b></div><div><small>Still available</small><b>${kg(remaining)}</b></div><div><small>Forecast fill rate</small><b>${fr===null?'Not supplied':num(fr)+'%'}</b></div><div><small>Average notice</small><b>${av===null?'No changes recorded':num(av)+' days'}</b></div></div><div class="planbottom"><span>${targets.length?`<b>${targets.length} potential ${p.stream==='Edible'?'food demand':'recovery'} match${targets.length===1?'':'es'}</b> · same state, period and category`:'No unfilled compatible demand yet. EFWA can review the gap.'}</span>${button(p.stream==='Edible'?'Find suitable demand':'Explore recovery partners','opportunities',p.id,targets.length>0)}</div></article>`}
function handovers(plans){const rows=state.matches.filter(m=>plans.some(p=>p.id===m.planId));return `<section class="panel" style="margin-top:28px"><div class="sectionhead"><div><span class="eyebrow">FROM PLAN TO OUTCOME</span><h2>Connections & handovers</h2></div>${badge('Demo confirmations')}</div>${rows.length?`<div class="tablewrap"><table><thead><tr><th>Material / destination</th><th>Period</th><th>Quantity</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(m=>{const p=state.plans.find(p=>p.id===m.planId),t=(m.kind==='food'?state.demands:state.partners).find(t=>t.id===m.targetId);return `<tr><td><b>${esc(p.material)}</b><small>${esc(t.organisation)} · ${p.region}</small></td><td>${period(p.period)}</td><td>${kg(m.qty)}</td><td>${badge(m.status,m.status==='Confirmed'?'green':'amber')}</td><td>${m.status==='Planned'?button('Confirm receipt','confirm',m.id)+button('Release','release',m.id):m.kind==='food'?`${m.people===null?'People count not reported':num(m.people)+' people reported'}`:'Recovery recorded'}</td></tr>`}).join('')}</tbody></table></div>`:'<p>No connections yet. Start with a plan and choose suitable demand.</p>'}</section>`}
function efwaPage(){const demands=filterRows(state.demands,filters),partners=filterRows(state.partners,filters);app.innerHTML=title('EFWA COORDINATOR WORKSPACE','Map demand. Coordinate the response.','Forecast food needs and identify possible destinations for inedible bakery material.',button('+ Add food demand','demand','',true))+filtersUI()+`<div class="stats three">${stat('Food demand forecast',kg(sum(demands)),`${demands.length} food demand records`)}${stat('Remaining food demand',kg(demands.reduce((s,d)=>s+remainingTarget(state,d),0)),'After reservations and confirmations','green')}${stat('Potential recovery capacity',kg(sum(partners)),`${partners.length} partner records · assessment required`)}</div><section class="panel"><div class="sectionhead"><div><span class="eyebrow">EDIBLE FOOD</span><h2>Demand forecasts</h2></div>${button('+ Add forecast','demand')}</div><p class="muted">State, period and bakery category define the first match. Product suitability and logistics still require agreement.</p><div class="tablewrap"><table><thead><tr><th>Receiving organisation</th><th>State / territory</th><th>Period</th><th>Category</th><th>Forecast</th><th>Still needed</th><th>Plan</th></tr></thead><tbody>${demands.map(d=>`<tr><td><b>${esc(d.organisation)}</b></td><td>${d.region}</td><td>${period(d.period)}</td><td>${esc(d.category)}</td><td>${kg(d.qty)}</td><td>${kg(remainingTarget(state,d))}</td><td>${button('Find supply','supply',d.id)}</td></tr>`).join('')||'<tr><td colspan="7">No demand forecasts for these filters. Add one to map a need.</td></tr>'}</tbody></table></div></section><section class="panel" style="margin-top:24px"><div class="sectionhead"><div><span class="eyebrow">INEDIBLE MATERIAL</span><h2>Possible recovery & transformation partners</h2></div>${button('+ Add partner','partner')}</div><p class="muted">Capacity is indicative. A partner must assess the material before any real handover.</p><div class="partnergrid">${partners.map(r=>`<article class="partnercard"><span class="pathwayicon">♧</span>${badge(r.pathway,'purple')}<h3>${esc(r.organisation)}</h3><p>${r.region} · ${period(r.period)}</p><strong>${kg(remainingTarget(state,r))} available</strong><p>${esc(r.requirements)}</p>${button('Find suitable material','recoverysupply',r.id)}</article>`).join('')||'<p>No recovery partners match these filters.</p>'}</div><div class="tip"><span>i</span><div><b>Dried food ingredients require food-safe inputs.</b> Register edible food-grade drying as food demand. Inedible material may be assessed for industrial drying, cosmetics, fermentation or fertiliser; it is not automatically suitable for food.</div></div></section><details class="programdetails"><summary>Coordination, governance & data policy</summary><div class="aboutgrid"><div><h3>EFWA convenes</h3><p>Bring the three business roles together to agree priorities, trials, measures and incentive funding. Businesses retain control of operational decisions.</p></div><div><h3>Partners agree</h3><p>Confirm intake requirements, material classification and collection responsibilities. Give smaller suppliers a voice in shared decisions.</p></div><div><h3>Share with consent</h3><p>Proposed policy: network-level aggregates, consent-based operational detail and no sharing of sensitive commercial terms across competitors. Review requirements before rollout.</p></div></div><p class="footnote">These are proposed program rules. This prototype does not enforce accounts, permissions or legal compliance.</p></details>`}
function openDialog(title,body,wide=false){modal.classList.toggle('wide',wide);modal.innerHTML=`<div class="dialoghead"><h2 id="dialog-title">${title}</h2><button data-action="close" aria-label="Close dialog">×</button></div>${body}`;if(!modal.open)modal.showModal()}
const field=(id,label,html,help='')=>`<div class="field"><label for="${id}">${label}</label>${html}${help?`<small>${help}</small>`:''}</div>`;
const input=(id,type='text',attrs='')=>`<input id="${id}" name="${id}" type="${type}" ${attrs}>`;
const select=(id,values,selected)=>`<select id="${id}" name="${id}">${opts(values,selected)}</select>`;
const regionField=()=>field('region','State / territory',select('region',Object.entries(REGIONS).map(([k,v])=>[k,`${v} (${k})`]),filters.region==='All'?'VIC':filters.region));
const periodField=()=>field('period','Planning period',select('period',PERIODS.map(p=>[p.id,p.label]),filters.period==='All'?'2026-11-30':filters.period));
const formEnd=(label)=>`<p class="formerror" role="alert"></p><div class="dialogactions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">${label}</button></div></form>`;
function formHandler(fn){$('#entryform').addEventListener('submit',e=>{e.preventDefault();try{fn(Object.fromEntries(new FormData(e.target)));save();modal.close();render()}catch(err){$('.formerror').textContent=err.message}})}
function number(v,label,allowZero=false){const n=Number(v);if(v===''||!Number.isFinite(n)||(allowZero?n<0:n<=0))throw Error(`Enter a valid ${label}.`);return n}
function planForm(){openDialog('Create a bakery waste plan',`<p>Enter the material you expect to have. Planning indicators are optional and do not set the surplus volume for you.</p><form id="entryform"><div class="formgrid">${field('business','Business name',input('business','text','required maxlength="80"'))}${field('role','Supply chain role',select('role',ROLES,role==='All'?ROLES[0]:role))}${regionField()}${periodField()}${field('material','Material / product',input('material','text','required maxlength="100" placeholder="e.g. Packed bread overrun"'))}${field('category','Bakery category',select('category',CATEGORIES,CATEGORIES[1]))}${field('stream','Material classification',select('stream',['Edible','Inedible'],'Edible'))}${field('reason','Reason / material profile',select('reason',['Order reduction','Unsold stock','Production overrun','Raw material surplus','Rejected batch','Expired / date review','Process by-product','Forecast uncertainty']))}${field('qty','Expected surplus / waste (kg)',input('qty','number','required min="1" step="1"'))}${field('handling','Handling, allergens & suitability',input('handling','text','required maxlength="400" placeholder="Ingredients, storage, dates, contamination…"'))}</div><p class="footnote">Rejected or date-affected stock needs assessment; its reason does not automatically determine whether it is edible.</p><details open><summary>Optional planning indicators</summary><div class="formgrid">${field('forecast','Forecast volume (kg)',input('forecast','number','min="1" step="1"'), 'Use the same period and unit as orders.')}${field('ordered','Actual volume ordered (kg)',input('ordered','number','min="0" step="1"'))}${field('notices','Days of notice for each order change',input('notices','text','placeholder="e.g. 2, 3, 1"'), 'Comma-separated non-negative days. Leave blank for no recorded changes.')}</div><div id="indicatorpreview" class="tip">Enter forecast and order volumes to see the fill rate.</div></details>${formEnd('Save business plan')}`,true);
const preview=()=>{try{const f=+$('#forecast').value,o=$('#ordered').value,days=parseNotices($('#notices').value);$('#indicatorpreview').textContent=`Forecast fill rate: ${f>0&&o!==''?num(fillRate(f,+o))+'%':'not supplied'}. Average notice: ${days.length?num(averageNotice(days))+' days':'no changes recorded'}. Use these to discuss order stability; enter the expected surplus separately.`}catch(e){$('#indicatorpreview').textContent=e.message}};['forecast','ordered','notices'].forEach(id=>$('#'+id).addEventListener('input',preview));formHandler(d=>{if(!d.business.trim()||!d.material.trim()||!d.handling.trim())throw Error('Complete the business, material and handling details.');let forecast=null,ordered=null;if(d.forecast!==''||d.ordered!==''){forecast=number(d.forecast,'forecast volume');ordered=number(d.ordered,'ordered volume',true)}state.plans.unshift({...d,business:d.business.trim(),material:d.material.trim(),id:crypto.randomUUID(),qty:number(d.qty,'planned quantity'),forecast,ordered,notices:parseNotices(d.notices)});business='All';role='All';toast('Business plan saved. Suitable demand is ready to explore.')})}
function parseNotices(value){if(!value.trim())return [];return value.split(',').map(v=>number(v.trim(),'notice period',true))}
function demandForm(isRecovery=false){openDialog(isRecovery?'Add a possible recovery partner':'Add a food demand forecast',`<p>${isRecovery?'Record indicative intake capacity. Technical acceptance is required before using any pathway.':'Record how much edible food or food-grade material is needed, where and when.'}</p><form id="entryform"><div class="formgrid">${field('organisation',isRecovery?'Partner organisation':'Receiving organisation',input('organisation','text','required maxlength="100"'))}${regionField()}${periodField()}${field('category','Accepted bakery category',select('category',CATEGORIES,isRecovery?CATEGORIES[3]:CATEGORIES[1]))}${field('qty',isRecovery?'Indicative capacity (kg)':'Demand forecast (kg)',input('qty','number','required min="1" step="1"'))}${isRecovery?field('pathway','Potential pathway',select('pathway',['Cosmetic ingredients','Industrial dried ingredients','Industrial fermentation','Fertiliser / compost','Anaerobic digestion'])):''}</div>${field('requirements','Acceptance requirements',`<textarea id="requirements" name="requirements" required maxlength="600" rows="3" placeholder="Material specifications, food safety, dates, packaging and logistics…"></textarea>`)}${formEnd(isRecovery?'Save recovery partner':'Save food demand')}`,true);formHandler(d=>{if(!d.organisation.trim()||!d.requirements.trim())throw Error('Enter an organisation and acceptance requirements.');(isRecovery?state.partners:state.demands).unshift({...d,id:crypto.randomUUID(),qty:number(d.qty,'capacity')});toast(isRecovery?'Recovery capacity added. Material assessment is still required.':'Demand forecast saved. Compatible business plans can now connect.')})}
function opportunities(planId){const p=state.plans.find(p=>p.id===planId);if(!p)return;const kind=p.stream==='Edible'?'food':'recovery',targets=potentialMatches(state,p);openDialog(p.stream==='Edible'?'Suitable demand opportunities':'Potential recovery opportunities',`<div class="dialogcontext"><b>${esc(p.material)}</b><p>${p.region} · ${period(p.period)} · ${esc(p.category)}</p><strong>${kg(remainingPlan(state,p))} still available</strong></div><p>These candidates share a state, period and category. Check requirements before reserving a connection.</p>${targets.map(t=>`<div class="matchcard"><div>${badge(kind==='food'?'Food demand':t.pathway,kind==='food'?'green':'purple')}<h3>${esc(t.organisation)}</h3><p>${esc(t.requirements)}</p><b>${kg(remainingTarget(state,t))} remaining</b></div>${button('Plan connection','match',`${p.id}|${t.id}|${kind}`,true)}</div>`).join('')||'<div class="empty"><h3>No compatible demand yet</h3><p>Ask EFWA to review the gap or revise the timing and material plan. Edible surplus stays edible until assessed otherwise.</p></div>'}`,true)}
function supplies(id,kind){const t=(kind==='food'?state.demands:state.partners).find(t=>t.id===id),plans=state.plans.filter(p=>compatible(p,t,kind)&&remainingPlan(state,p)>0);openDialog('Compatible business plans',`<p><b>${esc(t.organisation)}</b> · ${t.region} · ${period(t.period)}<br>${kg(remainingTarget(state,t))} remaining capacity</p>${remainingTarget(state,t)<=0?'<p>This demand is fully reserved.</p>':plans.map(p=>`<div class="matchcard"><div><h3>${esc(p.material)}</h3><p>${esc(p.business)} · ${kg(remainingPlan(state,p))} available</p><small>${esc(p.handling)}</small></div>${button('Plan connection','match',`${p.id}|${t.id}|${kind}`,true)}</div>`).join('')||'<p>No compatible business plan yet. Add a plan in Business planning.</p>'}`,true)}
function matchForm(key){const [planId,targetId,kind]=key.split('|'),p=state.plans.find(p=>p.id===planId),t=(kind==='food'?state.demands:state.partners).find(t=>t.id===targetId),max=Math.min(remainingPlan(state,p),remainingTarget(state,t));openDialog('Plan a connection',`<div class="dialogcontext"><b>${esc(p.business)} · ${esc(t.organisation)}</b><p>${esc(p.material)} · ${p.region} · ${period(p.period)}</p></div><h3>Receiving requirements</h3><p>${esc(t.requirements)}</p><h3>Business handling information</h3><p>${esc(p.handling)}</p><form id="entryform">${field('qty','Quantity to reserve (kg)',input('qty','number',`required min="1" max="${max}" step="1" value="${max}"`),`Maximum compatible quantity: ${kg(max)}.`)}<label class="checkbox"><input type="checkbox" required> I have reviewed the requirements for this demo connection.</label><p class="footnote">Planning reserves capacity only. Actual safety, suitability, acceptance and logistics are not verified here.</p>${formEnd('Reserve demo connection')}`);formHandler(d=>{addMatch(state,planId,targetId,kind,number(d.qty,'connection quantity'));toast('Connection reserved. It is not counted as managed waste until receipt is confirmed.')})}
function confirmForm(id){const m=state.matches.find(m=>m.id===id),p=state.plans.find(p=>p.id===m.planId);openDialog('Confirm a demo handover',`<p><b>${esc(p.material)}</b> · ${kg(m.qty)} · ${period(p.period)}</p><p>This confirms the entire reserved volume. To change it, release this connection and reserve the correct amount.</p><form id="entryform">${m.kind==='food'?field('people','People served (reported, optional)',input('people','number','min="0" step="1"'),'Use a reported count from the receiving partner. Leave blank if unknown. Do not estimate from weight.'):'<p>Inedible recovery does not contribute to people served.</p>'}<label class="checkbox"><input type="checkbox" required> Simulate both parties confirming receipt and suitability.</label><p class="footnote">This is demo evidence only. It updates reported outcomes for the plan’s period, including future periods if selected.</p>${formEnd('Confirm receipt')}`);formHandler(d=>{completeMatch(state,id,m.kind==='food'&&d.people!==''?Number(d.people):null);toast('Demo receipt confirmed. Reported outcomes updated once.')})}
function exportCSV(){const rows=[['Period','State','Category','Material stream','Managed kg','People served reported','Pathway'],...filterRows(outcomes(state),filters).map(o=>[period(o.period),o.region,o.category,o.stream,o.qty,o.people??'',o.pathway])];const safe=v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='foodloop-reported-outcomes.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case 'close':modal.close();break;case 'goto':location.hash=id;break;case 'clear':filters={region:'All',period:'All',category:'All'};render();break;case 'region':filters.region=id;render();break;case 'plan':planForm();break;case 'demand':demandForm();break;case 'partner':demandForm(true);break;case 'opportunities':opportunities(id);break;case 'supply':supplies(id,'food');break;case 'recoverysupply':supplies(id,'recovery');break;case 'match':matchForm(id);break;case 'confirm':confirmForm(id);break;case 'release':openDialog('Release this reservation?',`<p>The quantity will become available to both partners again. Confirmed outcomes will not be changed.</p><div class="dialogactions">${button('Keep reservation','close')}${button('Release reservation','releaseyes',id,true)}</div>`);break;case 'releaseyes':state.matches=state.matches.filter(m=>!(m.id===id&&m.status==='Planned'));save();modal.close();render();toast('Reservation released.');break;case 'export':exportCSV();break;case 'resetyes':state=seedData();filters={region:'All',period:'All',category:'All'};business='All';role='All';save();modal.close();render();toast('Illustrative demo data restored.');break}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;render()}if(e.target.id==='businessfilter'){business=e.target.value;render()}if(e.target.id==='rolefilter'){role=e.target.value;render()}});
$('#reset').onclick=()=>openDialog('Reset the prototype?',`<p>This replaces your browser’s plans, demands and outcomes with the original illustrative dataset.</p><div class="dialogactions">${button('Keep my changes','close')}${button('Reset demo data','resetyes','',true)}</div>`);
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render();window.scrollTo(0,0)});render();
